/**
 * Corporate Credit Card Approval Flow
 *
 * This flow handles hierarchical approval for corporate credit card requests:
 * 1. Requests approval from the requester's direct manager
 * 2. Waits 48 hours for manager approval
 * 3. If not approved within 48 hours, escalates to second-level manager
 * 4. Updates request status based on approval outcome
 *
 * Triggers when a new corporate credit card catalog item is requested
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const creditCardApprovalFlow = Flow(
    {
        $id: Now.ID['credit_card_approval_flow'],
        name: 'Corporate Credit Card Approval Flow',
        description: 'Hierarchical approval process for corporate credit card requests with automatic escalation',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['credit_card_request_trigger'] },
        {
            table: 'sc_req_item',
            condition: 'cat_item.nameLIKEcorporate credit card',
            run_flow_in: 'background',
        }
    ),
    (params) => {
        // Look up the requester details
        const requester = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_requester'],
                annotation: 'Retrieve requester details',
            },
            {
                table: 'sys_user',
                conditions: `sys_id=${wfa.dataPill(params.trigger.current.requested_for, 'reference')}`,
            }
        )

        // Look up the direct manager
        const directManager = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_direct_manager'],
                annotation: 'Retrieve direct manager details',
            },
            {
                table: 'sys_user',
                conditions: `sys_id=${wfa.dataPill(requester.Record.manager, 'reference')}`,
            }
        )

        // Step 1: Ask for direct manager approval
        wfa.action(
            action.core.askForApproval,
            {
                $id: Now.ID['request_manager_approval'],
                annotation: 'Request approval from direct manager',
            },
            {
                record: `${wfa.dataPill(params.trigger.current, 'reference')}`,
                table: 'sc_req_item',
                approval_reason: 'Please review and approve the corporate credit card request.',
                approval_field: 'approval',
                approval_conditions: wfa.approvalRules({
                    conditionType: 'OR',
                    ruleSets: [
                        {
                            action: 'Approves',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Any',
                                        users: [`${wfa.dataPill(directManager.Record.sys_id, 'string')}`],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                    ],
                }),
            }
        )

        // Step 2: Wait for 48 hours for manager approval
        wfa.flowLogic.waitForADuration({
            $id: Now.ID['wait_48_hours'],
            annotation: 'Wait 48 hours for manager approval',
            durationType: 'explicit_duration',
            duration: Duration({
                days: 2,
            }),
        })

        // Look up the approval record to check status
        const approvalCheck = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['check_approval_status'],
                annotation: 'Check if manager has approved',
            },
            {
                table: 'incident',
                conditions: `sysapproval=${wfa.dataPill(params.trigger.current.sys_id, 'reference')}^approver=${wfa.dataPill(directManager.Record.sys_id, 'reference')}`,
            }
        )

        // Step 3: Check if direct manager has approved
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(approvalCheck.Record.state, 'string')}=approved`,
                annotation: 'Check if direct manager approved',
                $id: Now.ID['check_manager_approved'],
            },
            () => {
                // Direct manager approved
                // Update request with approval notes
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['update_request_approved'],
                        annotation: 'Update request with approval confirmation',
                    },
                    {
                        table_name: 'sc_req_item',
                        record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                        values: TemplateValue({
                            work_notes: `Corporate credit card request approved by direct manager ${wfa.dataPill(directManager.Record.name, 'string')} on ${wfa.dataPill(approvalCheck.Record.sys_updated_on, 'string')}.`,
                        }),
                    }
                )

                // Send confirmation notification to requester
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['send_approval_confirmation'],
                        annotation: 'Send approval confirmation to requester',
                    },
                    {
                        record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                        notification: 'credit_card_approved_notification',
                    }
                )
            }
        )

        // Else if direct manager rejected
        wfa.flowLogic.elseIf(
            {
                condition: `${wfa.dataPill(approvalCheck.Record.state, 'string')}=rejected`,
                annotation: 'Check if direct manager rejected',
                $id: Now.ID['check_manager_rejected'],
            },
            () => {
                // Direct manager rejected
                // Update request with rejection notes
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['update_request_rejected'],
                        annotation: 'Update request with rejection details',
                    },
                    {
                        table_name: 'sc_req_item',
                        record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                        values: TemplateValue({
                            work_notes: `Corporate credit card request rejected by direct manager ${wfa.dataPill(directManager.Record.name, 'string')} on ${wfa.dataPill(approvalCheck.Record.sys_updated_on, 'string')}. Reason: ${wfa.dataPill(approvalCheck.Record.comments, 'string')}`,
                        }),
                    }
                )

                // Send rejection notification to requester
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['send_rejection_notification'],
                        annotation: 'Send rejection notification to requester',
                    },
                    {
                        record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                        notification: 'credit_card_rejected_notification',
                    }
                )
            }
        )

        // Else - Not approved or rejected within 48 hours, escalate to second-level manager
        wfa.flowLogic.else(
            {
                annotation: 'Escalate to second-level manager if no response in 48 hours',
                $id: Now.ID['escalate_to_second_level'],
            },
            () => {
                // Look up the second-level manager
                const secondLevelManager = wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_second_level_manager'],
                        annotation: 'Retrieve second-level manager details',
                    },
                    {
                        table: 'sys_user',
                        conditions: `sys_id=${wfa.dataPill(directManager.Record.manager, 'reference')}`,
                    }
                )

                // Log escalation
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_escalation'],
                        annotation: 'Log escalation to second-level manager',
                    },
                    {
                        log_level: 'warn',
                        log_message: `Credit card requested by ${wfa.dataPill(params.trigger.current.requested_for, 'string')} not approved within 48 hours by ${wfa.dataPill(directManager.Record.name, 'string')}, escalating to second-level manager: ${wfa.dataPill(secondLevelManager.Record.name, 'string')}`,
                    }
                )

                // Update request with escalation notes
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['update_request_escalated'],
                        annotation: 'Update request with escalation details',
                    },
                    {
                        table_name: 'sc_req_item',
                        record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                        values: TemplateValue({
                            work_notes: `Corporate credit card request escalated to second-level manager ${wfa.dataPill(secondLevelManager.Record.name, 'string')} after 48 hours without response from direct manager ${wfa.dataPill(directManager.Record.name, 'string')}.`,
                        }),
                    }
                )

                // Ask for second-level manager approval
                const secondLevelApproval = wfa.action(
                    action.core.askForApproval,
                    {
                        $id: Now.ID['request_second_level_approval'],
                        annotation: 'Request approval from second-level manager',
                    },
                    {
                        record: `${wfa.dataPill(params.trigger.current, 'reference')}`,
                        table: 'sc_req_item',
                        approval_reason:
                            'ESCALATED REQUEST: Please review and approve this corporate credit card request.',
                        approval_field: 'approval',
                        approval_conditions: wfa.approvalRules({
                            conditionType: 'OR',
                            ruleSets: [
                                {
                                    action: 'Approves',
                                    conditionType: 'AND',
                                    rules: [
                                        [
                                            {
                                                ruleType: 'Any',
                                                users: [`${wfa.dataPill(secondLevelManager.Record.sys_id, 'string')}`],
                                                groups: [],
                                                manual: false,
                                            },
                                        ],
                                    ],
                                },
                            ],
                        }),
                    }
                )

                // Check second-level manager approval result
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(secondLevelApproval.approval_state, 'string')}=approved`,
                        annotation: 'Check if second-level manager approved',
                        $id: Now.ID['check_second_level_approved'],
                    },
                    () => {
                        // Second-level manager approved
                        // Send approval notification to requester
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['send_escalated_approval'],
                                annotation: 'Send escalated approval notification',
                            },
                            {
                                record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                                notification: 'credit_card_escalated_approved_notification',
                            }
                        )
                    }
                )

                wfa.flowLogic.else(
                    {
                        annotation: 'Handle second-level manager rejection',
                        $id: Now.ID['handle_second_level_rejection'],
                    },
                    () => {
                        // Second-level manager rejected
                        // Send rejection notification to requester
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['send_escalated_rejection'],
                                annotation: 'Send escalated rejection notification',
                            },
                            {
                                record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                                notification: 'credit_card_escalated_rejected_notification',
                            }
                        )
                    }
                )
            }
        )
    }
)
